CREATE TABLE server (id INTEGER PRIMARY KEY CHECK(id=1), account_key TEXT NOT NULL, last_successful_sync INTEGER NOT NULL DEFAULT 0, catalog_synced INTEGER NOT NULL DEFAULT 0, playlist_checked_at INTEGER NOT NULL DEFAULT 0, playlist_audited_at INTEGER NOT NULL DEFAULT 0)
CREATE TABLE playlist (id TEXT PRIMARY KEY, name TEXT NOT NULL, changed TEXT NOT NULL, song_count INTEGER NOT NULL, duration INTEGER NOT NULL, detail_cached INTEGER NOT NULL DEFAULT 0, offline_sync INTEGER NOT NULL DEFAULT 0)
CREATE TABLE song (id TEXT PRIMARY KEY, title TEXT NOT NULL, artist TEXT NOT NULL, album TEXT NOT NULL, suffix TEXT NOT NULL, duration INTEGER NOT NULL, album_id TEXT NOT NULL DEFAULT '', track INTEGER NOT NULL DEFAULT 0, artist_id TEXT NOT NULL DEFAULT '', genre TEXT NOT NULL DEFAULT '', disc INTEGER NOT NULL DEFAULT 0, in_catalog INTEGER NOT NULL DEFAULT 0, audio_name TEXT NOT NULL DEFAULT '', cover_art TEXT NOT NULL DEFAULT '')
CREATE INDEX song_audio_name ON song(audio_name)
CREATE TABLE playlist_song (playlist_id TEXT NOT NULL, song_id TEXT NOT NULL, position INTEGER NOT NULL, PRIMARY KEY(playlist_id,position))
CREATE TABLE artist (id TEXT PRIMARY KEY, name TEXT NOT NULL)
CREATE TABLE album (id TEXT PRIMARY KEY, name TEXT NOT NULL, artist_id TEXT NOT NULL, artist TEXT NOT NULL)
CREATE TABLE download_queue (song_id TEXT PRIMARY KEY, position INTEGER NOT NULL, state INTEGER NOT NULL DEFAULT 0, received INTEGER NOT NULL DEFAULT 0, total INTEGER NOT NULL DEFAULT -1, error TEXT NOT NULL DEFAULT '', updated INTEGER NOT NULL DEFAULT 0)
CREATE TABLE audio_state (song_id TEXT PRIMARY KEY, downloaded_at INTEGER NOT NULL DEFAULT 0, last_played INTEGER NOT NULL DEFAULT 0, play_count INTEGER NOT NULL DEFAULT 0, pinned INTEGER NOT NULL DEFAULT 0)
CREATE TABLE local_song(id TEXT PRIMARY KEY,title TEXT NOT NULL,artist TEXT NOT NULL,album TEXT NOT NULL,suffix TEXT NOT NULL,duration INTEGER NOT NULL,album_id TEXT NOT NULL,track INTEGER NOT NULL,artist_id TEXT NOT NULL,genre TEXT NOT NULL,disc INTEGER NOT NULL,cover_art TEXT NOT NULL,path TEXT NOT NULL UNIQUE,bytes INTEGER NOT NULL,modified INTEGER NOT NULL)
CREATE TABLE track_like(account_key TEXT NOT NULL,song_id TEXT NOT NULL,liked INTEGER NOT NULL DEFAULT 0,revision INTEGER NOT NULL DEFAULT 0,dirty INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(account_key,song_id))
CREATE TABLE listen_event(session_id TEXT PRIMARY KEY,account_key TEXT NOT NULL,song_id TEXT NOT NULL,listened_at INTEGER NOT NULL)
CREATE INDEX listen_event_account ON listen_event(account_key,listened_at,session_id)
